'use strict';
class CityFilters{
 constructor(onChange){this.onChange=onChange;this.nomads=new Map();this.homicide=new Map();this.ready=false;this.error=false;this.q=new URLSearchParams(location.search);this.ids=['city-map-effect','nomads-enabled','nomads-min','cost-enabled','cost-max','crime-enabled','crime-max','crime-year'];for(const id of this.ids)document.getElementById(id).addEventListener('change',()=>{this.sync();onChange();});document.getElementById('city-filter-reset').onclick=()=>{document.getElementById('nomads-enabled').checked=document.getElementById('cost-enabled').checked=document.getElementById('crime-enabled').checked=false;document.getElementById('nomads-min').value=3;document.getElementById('cost-max').value=2500;document.getElementById('crime-max').value=5;document.getElementById('crime-year').value='2023';this.sync();onChange();};for(const id of ['nomads-min','cost-max','crime-max']){const slider=document.getElementById(id+'-slider'),input=document.getElementById(id);slider.addEventListener('input',()=>{input.value=slider.value;this.sync();clearTimeout(this.timer);this.timer=setTimeout(()=>onChange(),120);});input.addEventListener('input',()=>{this.sync();clearTimeout(this.timer);this.timer=setTimeout(()=>onChange(),120);});}document.getElementById('edit-city-filters').onclick=()=>{const panel=document.querySelector('.city-filter-controls');panel.open=true;panel.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.getElementById('nomads-enabled').focus({preventScroll:true});};document.querySelector('.city-filter-controls').addEventListener('focusin',e=>{requestAnimationFrame(()=>{const r=e.target.getBoundingClientRect(),nav=document.querySelector('.region-tabs').getBoundingClientRect();if(r.top<nav.bottom+12||r.bottom>innerHeight-16)e.target.scrollIntoView({block:'center',behavior:'instant'});});});this.load();}
 async load(){try{const [n,h]=await Promise.all([fetch('assets/nomads-cities.json?v=15').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('assets/homicide-country.json?v=15').then(r=>{if(!r.ok)throw Error();return r.json();})]);this.nomadsMeta=n;this.crimeMeta=h;for(const c of n.cities){if(!this.nomads.has(c.id)||c.match_km<this.nomads.get(c.id).match_km)this.nomads.set(c.id,c);}for(const r of h.rows)if(r.place_country)this.homicide.set(r.place_country+'|'+r.year,r);const select=document.getElementById('crime-year');select.replaceChildren();for(const year of Object.keys(h.coverage_by_year).reverse()){const o=document.createElement('option');o.value=year;o.textContent=`${year} · ${h.coverage_by_year[year]} mapped countries/areas`;select.append(o);}select.value=String(h.default_year);const set=(query,id,min,max,step)=>{const value=Number(this.q.get(query));if(this.q.has(query)&&Number.isFinite(value)&&value>=min&&value<=max&&Math.abs(value/step-Math.round(value/step))<1e-7)document.getElementById(id).value=value;};set('nomadmin','nomads-min',0,5,.1);set('budget','cost-max',0,1000000,50);set('hommax','crime-max',0,300,.1);if(h.coverage_by_year[this.q.get('homyear')])select.value=this.q.get('homyear');for(const [q,id]of [['nomads','nomads-enabled'],['cost','cost-enabled'],['crime','crime-enabled']])document.getElementById(id).checked=this.q.get(q)==='1';document.getElementById('city-map-effect').value=this.q.get('citymap')==='markers'?'markers':'ranking';this.ready=true;document.getElementById('nomads-date').textContent=`Snapshot retrieved ${new Date(n.retrieved_at).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'America/Sao_Paulo'})} · ${this.nomads.size.toLocaleString('en')} matched cities. Estimates change over time.`;document.getElementById('crime-date').textContent=`UNODC release ${h.source_updated}. Crime year is separate from the weather period. National context applies equally to all cities in a country.`;this.sync();this.onChange();}catch(e){this.error=true;this.ready=false;document.getElementById('city-filter-status').textContent='City comparison data could not load. Reload to retry; weather remains available.';this.onChange();}}
 sync(){for(const [toggle,input]of [['nomads-enabled','nomads-min'],['cost-enabled','cost-max'],['crime-enabled','crime-max']])document.getElementById(input).disabled=!this.ready||!document.getElementById(toggle).checked;document.getElementById('crime-year').disabled=!this.ready||!document.getElementById('crime-enabled').checked;for(const id of ['nomads-enabled','cost-enabled','crime-enabled'])document.getElementById(id).disabled=!this.ready;for(const id of ['nomads-min','cost-max','crime-max']){const slider=document.getElementById(id+'-slider'),input=document.getElementById(id);slider.disabled=input.disabled;slider.value=input.value;}const active=this.active;document.getElementById('city-filter-status').textContent=this.error?'City comparison data unavailable. Reload to retry.':!this.ready?'Loading city comparison data…':active?'Applied to the city ranking. Cities with missing required data are excluded. Map markers are optional; weather values stay unchanged.':'Off — all eligible weather cities remain in the ranking.';}
 get state(){const value=id=>Number(document.getElementById(id).value),checked=id=>document.getElementById(id).checked;return {nomads:checked('nomads-enabled'),minimum:value('nomads-min'),cost:checked('cost-enabled'),budget:value('cost-max'),crime:checked('crime-enabled'),maximum:value('crime-max'),year:value('crime-year')};}
 get active(){const s=this.state;return s.nomads||s.cost||s.crime;}
 get signature(){return JSON.stringify([this.ready,this.error,this.state]);}
 valid(){const s=this.state;return (!s.nomads||Number.isFinite(s.minimum)&&s.minimum>=0&&s.minimum<=5)&&(!s.cost||Number.isFinite(s.budget)&&s.budget>=0&&s.budget<=1000000)&&(!s.crime||Number.isFinite(s.maximum)&&s.maximum>=0&&s.maximum<=300);}
 reasons(e){if(!this.active)return [];if(!this.ready)return ['City data unavailable'];if(!this.valid())return ['Invalid filter value'];const s=this.state,n=this.nomads.get(e.place[0]),h=this.homicide.get(e.place[5]+'|'+s.year),reasons=[];if(s.nomads){if(!n||!Number.isFinite(n.score))reasons.push('Nomads score unavailable');else if(n.score<s.minimum)reasons.push(`Nomads ${n.score.toFixed(1)} < ${s.minimum}`);}if(s.cost){if(!n||!Number.isFinite(n.monthly_cost_usd)||n.monthly_cost_usd<=0)reasons.push('Monthly cost unavailable');else if(n.monthly_cost_usd>s.budget)reasons.push(`Monthly cost $${Math.round(n.monthly_cost_usd).toLocaleString('en')} > $${s.budget.toLocaleString('en')}`);}if(s.crime){if(!h||!Number.isFinite(h.value))reasons.push(`Country homicide unavailable for ${s.year}`);else if(h.value>s.maximum)reasons.push(`Country homicide ${h.value.toFixed(1)} > ${s.maximum} per 100,000 (${s.year})`);}return reasons;}
 allows(e){return this.reasons(e).length===0;}
 appendURL(q){const s=this.state;for(const key of ['nomads','nomadmin','cost','budget','crime','hommax','homyear','citymap'])q.delete(key);if(document.getElementById('city-map-effect').value==='markers')q.set('citymap','markers');if(s.nomads){q.set('nomads','1');q.set('nomadmin',s.minimum);}if(s.cost){q.set('cost','1');q.set('budget',s.budget);}if(s.crime){q.set('crime','1');q.set('hommax',s.maximum);q.set('homyear',s.year);}}
 details(place){const box=document.getElementById('city-context-values');box.replaceChildren();if(!place){box.textContent='Select a location to see city context.';return;}if(!this.ready){box.textContent='City comparison data unavailable.';return;}const n=this.nomads.get(place[0]),h=this.homicide.get(place[5]+'|'+this.state.year),fmt=v=>v.toLocaleString('en',{maximumFractionDigits:1});const add=(label,value,source,url)=>{const row=document.createElement('div'),term=document.createElement('dt'),desc=document.createElement('dd'),a=document.createElement('a');term.textContent=label;desc.textContent=value+' ';a.textContent=source;a.href=url;a.target='_blank';a.rel='noopener';desc.append(a);row.append(term,desc);box.append(row);};if(this.active){const reasons=this.reasons({place});add('Your city filters',reasons.length?'Excluded · '+reasons.join('; '):'Matches your city filters','Filter settings','#city-filter-status');}add('Nomads score',n?fmt(n.score)+' / 5':'Not available','Nomads.com',n?'https://nomads.com/'+n.slug:'https://nomads.com/');add('Nomad monthly cost',n&&n.monthly_cost_usd>0?'$'+fmt(n.monthly_cost_usd)+' USD estimate':'Not available','Nomads.com',n?'https://nomads.com/'+n.slug:'https://nomads.com/');add(`Country homicide · ${this.state.year}`,h?`${fmt(h.value)} per 100,000 · ${h.country}`:'Not available for '+place[5],'UNODC','https://data.unodc.org/datareport/hom-victim');}
}
window.CityFilters=CityFilters;
